package owl.nh;
public final class OlmLoopTests {
 static void check(boolean condition,String message){CoreTests.check(condition,"Olm loop: "+message);}
 public static void main(String[] args)throws Exception{
  check(OlmDeathRecovery.onOutsideSide(new OlmSpecials.Cell(0,-2,0),new OlmSpecials.Cell(0,0,0),new OlmSpecials.Cell(0,-3,0))&&!OlmDeathRecovery.onOutsideSide(new OlmSpecials.Cell(0,2,0),new OlmSpecials.Cell(0,0,0),new OlmSpecials.Cell(0,-3,0)),"gate-side evidence distinguishes the pre-room from the fight side");OlmLoopPlan p=new OlmLoopPlan();char[] secret="test-only".toCharArray();p.start(2,true,secret);java.util.Arrays.fill(secret,'x');check(p.password().equals("test-only"),"session owns an isolated secret copy");p.disconnected(100);check(!p.mayLogin(30000000099L)&&p.mayLogin(30000000100L),"login is gated by a full 30-second delay");p.submitted(30000000100L);check(!p.mayLogin(30000000101L),"login requests are not spammed");check(p.completed==0,"disconnect and login requests never count as kills");p.connected();check(p.disconnectedAt<0,"confirmed connection clears reconnect state");p.completedRaid();check(p.active&&p.next&&p.completed==1,"completed loot/reset/entry schedules the next cycle");p.next=false;p.completedRaid();check(!p.active&&p.completed==2&&p.password().isEmpty(),"goal completion stops and clears the secret");p.start(3,true,"test".toCharArray());p.cancel();check(!p.active&&!p.reconnect&&p.password().isEmpty(),"Stop cancels reconnect and wipes session secret");boolean invalid=false;try{p.start(0,false,null);}catch(IllegalArgumentException expected){invalid=true;}check(invalid,"invalid goals cannot start");runtimeDisconnect();deathRecovery();System.out.println("Olm loop checks passed: exact cycle goal, 30-second reconnect, no phantom kills, cancellation and session secret cleanup. Synthetic only.");}
 private static void deathRecovery()throws Exception{
  OlmDeathRecovery recovery=new OlmDeathRecovery();OlmSpecials.Cell death=new OlmSpecials.Cell(0,0,0),lobby=new OlmSpecials.Cell(0,10,0);recovery.start(100,death);recovery.observe(101,false,death,true,false);check(recovery.stage==OlmDeathRecovery.Stage.RESPAWN,"dead player cannot issue recovery input");recovery.observe(102,true,death,true,false);check(recovery.stage==OlmDeathRecovery.Stage.RESPAWN,"health returning at the death tile is not a confirmed respawn");recovery.observe(103,true,lobby,true,false);recovery.observe(103,true,lobby,true,false);check(recovery.stage==OlmDeathRecovery.Stage.RESPAWN,"duplicate client cycles cannot confirm lobby arrival");recovery.observe(104,true,lobby,true,false);check(recovery.stage==OlmDeathRecovery.Stage.EXIT&&recovery.due(104),"observed pre-room respawn enables the rope exit");recovery.ropeRequested(104);check(!recovery.due(105),"rope click waits for confirmation instead of spamming");recovery.observe(105,true,lobby,false,true);check(recovery.stage==OlmDeathRecovery.Stage.EXIT,"one outside frame is not enough to start banking");recovery.observe(106,true,lobby,false,true);check(recovery.stage==OlmDeathRecovery.Stage.OUTSIDE,"stable outside evidence permits the normal restock routine");
  check("Climb".equals(OlmDeathRecovery.ropeAction("Rope",new String[]{"Climb","Examine"}))&&OlmDeathRecovery.ropeAction("Olm barrier",new String[]{"Enter"})==null,"recovery only selects the exit rope, never the fight gate");check(OlmDeathRecovery.confirmLeave("<col=ff0000>Yes, leave the raid</col>")&&!OlmDeathRecovery.confirmLeave("No, stay here")&&!OlmDeathRecovery.confirmLeave("Do not leave the raid"),"exit dialogue accepts affirmative confirmation only");recovery.start(200,death);recovery.observe(201,true,lobby,false,false);check(recovery.stage==OlmDeathRecovery.Stage.RESPAWN&&recovery.timedOut(400),"unrecognized respawn location waits with a bounded timeout");recovery.reset();check(recovery.stage==OlmDeathRecovery.Stage.IDLE&&!recovery.due(1000),"Stop removes recovery actions");
  java.util.Map<String,Object> fields=new java.util.HashMap<>();fields.put("getGameState",net.runelite.api.GameState.LOGGED_IN);fields.put("getTickCount",10);fields.put("getGameCycle",10);net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,fields);java.lang.reflect.Constructor<net.runelite.client.callback.ClientThread> ctor=net.runelite.client.callback.ClientThread.class.getDeclaredConstructor(net.runelite.api.Client.class);ctor.setAccessible(true);CombatRuntime runtime=new CombatRuntime(client,ctor.newInstance(client),new net.runelite.client.eventbus.EventBus(),null);
  try{runtime.olmLoop.start(3,false,null);runtime.olmLoop.plan.completed=1;runtime.olm.running=true;java.lang.reflect.Field attemptField=OlmFighter.class.getDeclaredField("attempt");attemptField.setAccessible(true);((OlmAttemptLifecycle)attemptField.get(runtime.olm)).start(10);java.lang.reflect.Method end=OlmFighter.class.getDeclaredMethod("endAttempt",String.class,String.class);end.setAccessible(true);end.invoke(runtime.olm,"DEATH","Synthetic death");java.lang.reflect.Field deathFlag=OlmFighter.class.getDeclaredField("recoveringDeathRaid");deathFlag.setAccessible(true);check(runtime.olmLoop.plan.active&&runtime.olmLoop.plan.completed==1&&!runtime.olmLoop.plan.next&&runtime.olm.running&&deathFlag.getBoolean(runtime.olm),"production death hook preserves loop goal, gives zero kill credit and waits for reset");runtime.stop("Test Stop during recovery");check(!runtime.olmLoop.plan.active&&!runtime.olm.running&&!deathFlag.getBoolean(runtime.olm),"F9 equivalent cancels death recovery and the loop");}finally{runtime.olm.close();}
 }
 private static void runtimeDisconnect()throws Exception{
  java.util.Map<String,Object> fields=new java.util.HashMap<>();fields.put("getGameState",net.runelite.api.GameState.LOGIN_SCREEN);fields.put("getTickCount",10);fields.put("getGameCycle",10);fields.put("getPlayers",java.util.Collections.emptyList());net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,fields);java.lang.reflect.Constructor<net.runelite.client.callback.ClientThread> ctor=net.runelite.client.callback.ClientThread.class.getDeclaredConstructor(net.runelite.api.Client.class);ctor.setAccessible(true);CombatRuntime r=new CombatRuntime(client,ctor.newInstance(client),new net.runelite.client.eventbus.EventBus(),null);
  try{r.olmLoop.start(2,true,"test-only".toCharArray());r.olm.running=true;r.onGameTick(new net.runelite.api.events.GameTick());check(r.olmLoop.plan.active&&r.olm.running&&r.olmLoop.plan.completed==0,"runtime login-screen ticks pause instead of cancelling the active loop");check(r.olmLoop.plan.disconnectedAt>=0,"runtime records disconnect without emitting login input before delay");r.olmLoop.retryInterruptedRaid();check(r.olmLoop.plan.next&&r.olmLoop.plan.completed==0,"outside recovery reschedules without inventing a completed kill");r.stop("Test Stop");check(!r.olmLoop.plan.active&&!r.olm.running&&r.olmLoop.plan.password().isEmpty(),"actual Stop cancels the loop and credentials");}finally{r.olm.close();}
 }}

